    unsigned b785 = stwo_m31_add(b783, b784);
    unsigned b786 = stwo_m31_mul(b124, b283);
    unsigned b787 = stwo_m31_add(b785, b786);
    unsigned b788 = stwo_m31_mul(b125, b280);
    unsigned b789 = stwo_m31_add(b787, b788);
    unsigned b790 = stwo_m31_mul(b126, b277);
    unsigned b791 = stwo_m31_add(b789, b790);
    unsigned b857 = stwo_m31_sub(b856, b791);
    unsigned b858 = stwo_m31_add(b762, b857);
    unsigned b864 = stwo_m31_sub(b698, b858);
    unsigned b865 = stwo_m31_add(b176, b864);
    unsigned b866 = base_params[406u];
    unsigned b867 = stwo_m31_mul(b865, b866);
    unsigned b868 = stwo_m31_sub(b177, b867);
    StwoCudaQm31 e1 = StwoCudaQm31{ b868, b178, b178, b178 };
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e1, stwo_load_qm31(random_coeff_powers, rc_base + 1u)));

    // Fused denom_inv multiply + in-place accumulator update.
    unsigned denom_idx = row_index >> log_n_rows;
    StwoCudaQm31 result = stwo_qm31_mul_base(acc, denom_inv[denom_idx]);
    coord_0[row_index] = stwo_m31_add(coord_0[row_index], result.a);
    coord_1[row_index] = stwo_m31_add(coord_1[row_index], result.b);
    coord_2[row_index] = stwo_m31_add(coord_2[row_index], result.c);
    coord_3[row_index] = stwo_m31_add(coord_3[row_index], result.d);
}
